// ─────────────────────────────────────────────────────────────────────
// Node: Verify Signature & Normalize Event    Mode: Run Once for All Items
// Repo: n8n-zoom-webinar-hubspot-engagement-sync · dhRobin Systems
// Zoom signs every delivery: x-zm-signature = "v0=" + hex HMAC-SHA256 of
// "v0:{x-zm-request-timestamp}:{raw body}", keyed with the app's Secret Token.
// • endpoint.url_validation → { plainToken, encryptedToken } (signature checked
//   first; plainTokens that could be abused as a signing oracle are refused)
// • webinar.registration_created / participant_joined / participant_left →
//   one engagement item for the contact pipeline
// • webinar.ended → one report item (attendance + Q&A summaries per attendee)
// Replay window, idempotency ledger, e-mail normalisation, internal-domain filter.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const helpers = this.helpers;
let crypto = null;
try { crypto = require('crypto'); } catch (error) { crypto = null; }

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const PERSIST = !SANDBOX_MODE && !DRY_RUN;
const SANDBOX_SECRET = 'sandbox-fictional-zoom-secret-token-not-for-production';
const SECRET = env('ZOOM_WEBHOOK_SECRET', '') || (SANDBOX_MODE ? SANDBOX_SECRET : '');
const TOLERANCE = Math.max(30, num('ZOOM_SIGNATURE_TOLERANCE_SECONDS', 300));
const EVENTS = new Set(csv('PROCESS_EVENT_TYPES', 'webinar.registration_created,webinar.participant_joined,webinar.participant_left,webinar.ended'));
const INTERNAL = new Set(csv('INTERNAL_EMAIL_DOMAINS', 'YOUR_COMPANY_DOMAIN.example').map((d) => d.toLowerCase()));
// Sandbox fixtures add their own fictional internal domain after the items are read (see below).
const WEBINAR_IDS = csv('WEBINAR_ID_ALLOWLIST', '');
const LEDGER_DAYS = Math.max(1, num('EVENT_LEDGER_DAYS', 30));

let runId;
try { runId = 'zw_' + crypto.randomUUID(); } catch (error) { runId = 'zw_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }
const run = { runId, startedAt: new Date().toISOString(), mode: SANDBOX_MODE ? 'sandbox' : DRY_RUN ? 'dry_run' : 'live', sandboxMode: SANDBOX_MODE, dryRun: DRY_RUN };
const items = $input.all();
const sharedFixtures = SANDBOX_MODE ? ((items.find((i) => i.json.sandboxFixtures) || { json: {} }).json.sandboxFixtures || null) : null;
if (sharedFixtures && Array.isArray(sharedFixtures.internalDomains)) for (const d of sharedFixtures.internalDomains) INTERNAL.add(String(d).toLowerCase());

const sha = (s) => crypto.createHash('sha256').update(String(s)).digest();
const safeEqual = (a, b) => !!crypto && typeof a === 'string' && typeof b === 'string' && a.length > 0 && b.length > 0 && crypto.timingSafeEqual(sha(a), sha(b));
const hmacHex = (msg) => crypto.createHmac('sha256', SECRET).update(msg, 'utf8').digest('hex');

function verify(headers, raw) {
  if (!crypto) return { ok: false, reason: 'crypto_module_unavailable' };
  if (!SECRET) return { ok: false, reason: 'webhook_secret_not_configured' };
  const sig = String(headers['x-zm-signature'] || '').trim();
  const ts = String(headers['x-zm-request-timestamp'] || '').trim();
  if (!sig) return { ok: false, reason: 'signature_header_missing' };
  if (!/^\d{10,13}$/.test(ts)) return { ok: false, reason: 'timestamp_header_missing' };
  if (!safeEqual(sig.toLowerCase(), `v0=${hmacHex(`v0:${ts}:${raw}`)}`)) return { ok: false, reason: 'signature_mismatch' };
  const tsSec = ts.length > 10 ? Math.floor(Number(ts) / 1000) : Number(ts);
  // Fixtures carry fixed timestamps, so the replay window is enforced outside sandbox only.
  if (!SANDBOX_MODE && Math.abs(Date.now() / 1000 - tsSec) > TOLERANCE) return { ok: false, reason: 'timestamp_outside_tolerance' };
  return { ok: true };
}

const email = (v) => { const s = String(v || '').trim().toLowerCase(); return /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(s) ? s : null; };
const iso = (v) => { if (!v) return null; const d = new Date(v); return Number.isNaN(d.getTime()) ? null : d.toISOString(); };
const uuidPath = (u) => (u && (u.startsWith('/') || u.includes('//')) ? encodeURIComponent(encodeURIComponent(u)) : encodeURIComponent(u || ''));

const staticData = $getWorkflowStaticData('global');
const ledger = PERSIST ? (staticData.zoomEngagementLedger = staticData.zoomEngagementLedger || {}) : JSON.parse(JSON.stringify(staticData.zoomEngagementLedger || {}));
const joins = PERSIST ? (staticData.zoomOpenSessions = staticData.zoomOpenSessions || {}) : JSON.parse(JSON.stringify(staticData.zoomOpenSessions || {}));
const nowMs = Date.now();
for (const [k, v] of Object.entries(ledger)) if (!v || nowMs - v.at > LEDGER_DAYS * 86400000) delete ledger[k];
for (const [k, v] of Object.entries(joins)) if (!v || nowMs - v.at > 2 * 86400000) delete joins[k];
const seen = new Set();

const out = [];
for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const headers = {};
  for (const [k, v] of Object.entries(item.json.headers || {})) headers[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0]) : String(v);
  let raw = null;
  if (item.binary && item.binary.data) { try { raw = (await helpers.getBinaryDataBuffer(index, 'data')).toString('utf8'); } catch (e) { raw = null; } }
  let body = item.json.body;
  if ((!body || (typeof body === 'object' && !Object.keys(body).length)) && raw) { try { body = JSON.parse(raw); } catch (e) { body = null; } }
  if (raw === null) raw = typeof body === 'string' ? body : JSON.stringify(body ?? {});
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const b = body && typeof body === 'object' ? body : {};
  const base = { run, sandboxFixtures: sharedFixtures, deliveryRef: `delivery-${index + 1}`, eventName: b.event ? String(b.event).slice(0, 60) : null };

  const v = verify(headers, raw);
  if (!v.ok) { out.push({ json: { ...base, kind: 'rejected', reason: v.reason, httpStatus: 401, response: { message: 'invalid signature' } } }); continue; }

  if (b.event === 'endpoint.url_validation') {
    const plain = b.payload && typeof b.payload.plainToken === 'string' ? b.payload.plainToken : '';
    // A signing oracle guard: only short token-like strings are echoed back as HMACs.
    if (!/^[A-Za-z0-9_-]{8,64}$/.test(plain)) { out.push({ json: { ...base, kind: 'rejected', reason: 'invalid_plain_token', httpStatus: 400, response: { message: 'invalid plainToken' } } }); continue; }
    out.push({ json: { ...base, kind: 'url_validation', httpStatus: 200, response: { plainToken: plain, encryptedToken: hmacHex(plain) } } });
    continue;
  }
  const ignore = (reason, extra = {}) => out.push({ json: { ...base, kind: 'ignored', reason, httpStatus: 200, response: { status: 'ignored' }, ...extra } });
  if (!EVENTS.has(String(b.event))) { ignore('event_type_not_processed'); continue; }
  const o = (b.payload && b.payload.object) || {};
  const webinar = { id: o.id != null ? String(o.id) : null, uuid: o.uuid ? String(o.uuid) : null, uuidPath: uuidPath(o.uuid), topic: o.topic ? String(o.topic).slice(0, 200) : null,
    startTime: iso(o.start_time), endTime: iso(o.end_time), scheduledMinutes: Number(o.duration) > 0 ? Number(o.duration) : null, timezone: o.timezone || null };
  if (WEBINAR_IDS.length && !WEBINAR_IDS.includes(webinar.id)) { ignore('webinar_not_in_allowlist', { webinar }); continue; }
  const eventTs = Number(b.event_ts) || nowMs;

  if (b.event === 'webinar.ended') {
    const key = `ended:${webinar.uuid}`;
    if (seen.has(key) || ledger[key]) { ignore('duplicate_event', { webinar }); continue; }
    seen.add(key);
    out.push({ json: { ...base, kind: 'event', route: 'report', httpStatus: 200, response: { status: 'received' }, ledgerKey: key, webinar } });
    continue;
  }

  let engagement;
  if (b.event === 'webinar.registration_created') {
    const r = o.registrant || {};
    engagement = { type: 'registered', email: email(r.email), registrantId: r.id ? String(r.id) : null, occurredAt: iso(r.create_time) || new Date(eventTs).toISOString(),
      firstName: r.first_name ? String(r.first_name).slice(0, 80) : null, lastName: r.last_name ? String(r.last_name).slice(0, 80) : null,
      company: r.org ? String(r.org).slice(0, 120) : null, jobTitle: r.job_title ? String(r.job_title).slice(0, 120) : null, status: r.status || null };
  } else {
    const p = o.participant || {};
    const pid = String(p.participant_uuid || p.user_id || p.id || '');
    engagement = { type: b.event === 'webinar.participant_joined' ? 'joined' : 'left', email: email(p.email), registrantId: p.registrant_id ? String(p.registrant_id) : null, participantKey: pid || null,
      occurredAt: iso(b.event === 'webinar.participant_joined' ? p.join_time : p.leave_time) || new Date(eventTs).toISOString(), leaveReason: p.leave_reason ? String(p.leave_reason).slice(0, 120) : null };
    const sessionKey = `${webinar.uuid}:${pid}`;
    if (engagement.type === 'joined' && pid) joins[sessionKey] = { at: nowMs, joinTime: engagement.occurredAt };
    if (engagement.type === 'left') {
      const joinIso = iso(p.join_time) || (joins[sessionKey] && joins[sessionKey].joinTime) || null;
      engagement.joinTime = joinIso;
      engagement.sessionMinutes = joinIso ? Math.max(0, Math.round((Date.parse(engagement.occurredAt) - Date.parse(joinIso)) / 60000)) : null;
      delete joins[sessionKey];
    }
  }
  if (!engagement.email) { ignore('participant_without_email', { webinar, engagementType: engagement.type }); continue; }
  if (INTERNAL.has(engagement.email.split('@')[1])) { ignore('internal_email_domain', { webinar, engagementType: engagement.type }); continue; }
  const key = `${engagement.type}:${webinar.uuid}:${engagement.email}:${engagement.participantKey || engagement.registrantId || ''}:${engagement.occurredAt}`;
  if (seen.has(key) || ledger[key]) { ignore('duplicate_event', { webinar, engagementType: engagement.type }); continue; }
  seen.add(key);
  out.push({ json: { ...base, kind: 'event', route: 'contact', httpStatus: 200, response: { status: 'received' }, ledgerKey: key, webinar, engagement } });
}
return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Simulate Zoom Reports (Sandbox)       Mode: Run Once for Each Item
// Fictional participant and Q&A reports in the shapes returned by
// GET /report/webinars/{uuid}/participants and /report/webinars/{uuid}/qa.
// ─────────────────────────────────────────────────────────────────────
const item = $json;
const rep = ((item.sandboxFixtures || {}).reports || {})[item.webinar.uuid] || { participants: [], questions: [] };
return { json: { ...item, simulatedReports: { participantPages: [{ statusCode: 200, body: { page_size: 300, total_records: rep.participants.length, next_page_token: '', participants: rep.participants } }],
  qa: { statusCode: 200, body: { id: Number(item.webinar.id), uuid: item.webinar.uuid, questions: rep.questions } } } } };

// ─────────────────────────────────────────────────────────────────────
// Node: Build Attendance Summaries            Mode: Run Once for All Items
// After webinar.ended: merges every session per attendee (rejoins are
// separate report rows), adds Q&A participation, scores engagement and
// emits one 'attended' engagement item per external attendee.
//   attendance % = attended minutes / webinar minutes (actual, else scheduled)
//   tier: hot   ≥ HOT_ATTENDANCE_PCT (75) or (≥ 50 % and asked a question)
//         warm  ≥ WARM_ATTENDANCE_PCT (40) or asked a question
//         cold  attended, below warm · brief: under MIN_ATTENDED_MINUTES (5)
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const HOT = num('HOT_ATTENDANCE_PCT', 75);
const WARM = num('WARM_ATTENDANCE_PCT', 40);
const MIN_MIN = num('MIN_ATTENDED_MINUTES', 5);
const INCLUDE_Q_TEXT = flag('INCLUDE_QUESTION_TEXT', false);
const INTERNAL = new Set(csv('INTERNAL_EMAIL_DOMAINS', 'YOUR_COMPANY_DOMAIN.example').map((d) => d.toLowerCase()));
const email = (v) => { const s = String(v || '').trim().toLowerCase(); return /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(s) ? s : null; };

const first = $input.first().json;
const sandbox = !!(first && first.simulatedReports);
const ctx = sandbox ? first : $('Webinar Ended?').first().json;
const pages = sandbox ? first.simulatedReports.participantPages : $input.all().map((i) => i.json);
let qaRes = sandbox ? first.simulatedReports.qa : null;
if (!sandbox) { try { qaRes = $('Fetch Q&A Report').first().json; } catch (e) { qaRes = null; } }
const errors = [];
const rows = [];
for (const p of pages) { if (Number(p.statusCode) === 200 && p.body && Array.isArray(p.body.participants)) rows.push(...p.body.participants); else errors.push(`participants report ${p.statusCode || 'network error'}`); }
const questions = qaRes && Number(qaRes.statusCode) === 200 && qaRes.body && Array.isArray(qaRes.body.questions) ? qaRes.body.questions : [];
if (qaRes && Number(qaRes.statusCode) !== 200) errors.push(`Q&A report ${qaRes.statusCode || 'network error'}`);

const w = ctx.webinar;
if (ctx.sandboxFixtures && Array.isArray(ctx.sandboxFixtures.internalDomains)) for (const d of ctx.sandboxFixtures.internalDomains) INTERNAL.add(String(d).toLowerCase());
const spanMinutes = (() => { const t = rows.map((r) => [Date.parse(r.join_time), Date.parse(r.leave_time)]).filter(([a, b]) => a && b); if (!t.length) return null; return Math.round((Math.max(...t.map((x) => x[1])) - Math.min(...t.map((x) => x[0]))) / 60000); })();
const webinarMinutes = (w.startTime && w.endTime ? Math.round((Date.parse(w.endTime) - Date.parse(w.startTime)) / 60000) : null) || w.scheduledMinutes || spanMinutes || 60;
const stats = { reportRows: rows.length, excludedInternal: 0, excludedNoEmail: 0, attendees: 0, questions: questions.length, webinarMinutes, errors };

const by = {};
for (const r of rows) {
  const e = email(r.user_email || r.email);
  if (!e) { stats.excludedNoEmail++; continue; }
  if (INTERNAL.has(e.split('@')[1])) { stats.excludedInternal++; continue; }
  const a = (by[e] = by[e] || { email: e, seconds: 0, sessions: 0, firstJoin: null, lastLeave: null, registrantId: r.registrant_id || null, intervals: [] });
  const j = Date.parse(r.join_time); const l = Date.parse(r.leave_time);
  if (j && l && l > j) a.intervals.push([j, l]);
  else a.seconds += Math.max(0, Number(r.duration) || 0);
  a.sessions++;
  if (j && (!a.firstJoin || j < a.firstJoin)) a.firstJoin = j;
  if (l && (!a.lastLeave || l > a.lastLeave)) a.lastLeave = l;
}
// Merge overlapping intervals so two devices for one person aren't double-counted.
for (const a of Object.values(by)) {
  const iv = a.intervals.sort((x, y) => x[0] - y[0]); let cur = null;
  for (const [s, e] of iv) { if (!cur || s > cur[1]) { if (cur) a.seconds += (cur[1] - cur[0]) / 1000; cur = [s, e]; } else cur[1] = Math.max(cur[1], e); }
  if (cur) a.seconds += (cur[1] - cur[0]) / 1000;
}
const qa = {};
for (const q of questions) {
  const e = email(q.email); if (!e) continue;
  const d = Array.isArray(q.question_details) ? q.question_details : [];
  const x = (qa[e] = qa[e] || { asked: 0, answered: 0, firstQuestion: null });
  for (const qd of d) { x.asked++; if (qd.answer || (qd.question_status && qd.question_status !== 'open')) x.answered++; if (!x.firstQuestion && qd.question) x.firstQuestion = String(qd.question).slice(0, 200); }
}
let ledger = {};
try { ledger = $getWorkflowStaticData('global').zoomEngagementLedger || {}; } catch (e) { ledger = {}; }
stats.alreadySynced = 0;
const out = [];
for (const a of Object.values(by)) {
  if (ledger[`attended:${w.uuid}:${a.email}`]) { stats.alreadySynced++; continue; } // a redelivered webinar.ended

  const minutes = Math.round(a.seconds / 60);
  const pct = Math.min(100, Math.round((minutes / webinarMinutes) * 100));
  const q = qa[a.email] || { asked: 0, answered: 0, firstQuestion: null };
  const tier = minutes < MIN_MIN ? 'brief' : pct >= HOT || (pct >= 50 && q.asked > 0) ? 'hot' : pct >= WARM || q.asked > 0 ? 'warm' : 'cold';
  stats.attendees++;
  out.push({ json: { run: ctx.run, sandboxFixtures: ctx.sandboxFixtures, deliveryRef: ctx.deliveryRef, eventName: 'webinar.ended', kind: 'event', route: 'contact', ledgerKey: `attended:${w.uuid}:${a.email}`, webinar: w,
    engagement: { type: 'attended', email: a.email, registrantId: a.registrantId, occurredAt: new Date(a.lastLeave || Date.now()).toISOString(), firstJoin: a.firstJoin ? new Date(a.firstJoin).toISOString() : null,
      lastLeave: a.lastLeave ? new Date(a.lastLeave).toISOString() : null, attendedMinutes: minutes, attendancePct: pct, sessions: a.sessions, questionsAsked: q.asked, questionsAnswered: q.answered,
      firstQuestion: INCLUDE_Q_TEXT ? q.firstQuestion : null, engagementTier: tier }, reportStats: stats } });
}
if (!out.length) out.push({ json: { run: ctx.run, deliveryRef: ctx.deliveryRef, eventName: 'webinar.ended', kind: 'ignored', reason: errors.length ? 'report_unavailable' : stats.alreadySynced ? 'already_synced' : 'no_external_attendees', webinar: w, reportStats: stats } });
return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Build Contact Lookup                  Mode: Run Once for Each Item
// Primary e-mail first, then HubSpot's additional e-mails.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const P = env('ZOOM_PROPERTY_PREFIX', 'zoom_');
const e = $json.engagement.email;
return { json: { ...$json, prefix: P, contactSearch: {
  filterGroups: [{ filters: [{ propertyName: 'email', operator: 'EQ', value: e }] }, { filters: [{ propertyName: 'hs_additional_emails', operator: 'CONTAINS_TOKEN', value: e }] }],
  properties: ['email', 'firstname', 'lastname', 'hs_additional_emails', ...['webinars_registered_count', 'webinars_attended_count', 'webinar_minutes_total', 'webinar_questions_total', 'last_webinar_uuid',
    'last_webinar_registered_uuid', 'last_webinar_attended_at', 'webinar_engagement_tier'].map((x) => `${P}${x}`)], limit: 5 } } };

// ─────────────────────────────────────────────────────────────────────
// Node: Simulate Contact Search (Sandbox)     Mode: Run Once for Each Item
// ─────────────────────────────────────────────────────────────────────
const item = $json; const e = item.engagement.email;
const list = ((item.sandboxFixtures || {}).contacts || []).filter((c) => c.properties.email === e || String(c.properties.hs_additional_emails || '').toLowerCase().split(';').includes(e));
return { json: { ...item, simulatedContact: { statusCode: 200, body: { total: list.length, results: list.map((c) => ({ id: c.id, properties: c.properties })) } } } };

// ─────────────────────────────────────────────────────────────────────
// Node: Plan Contact & Custom Event Updates   Mode: Run Once for Each Item
// Contact: primary e-mail match, else additional e-mail. Unknown e-mails are
// created only for registrations (CREATE_CONTACT_ON_REGISTRATION) or, if
// enabled, attendees (CREATE_CONTACT_FOR_ATTENDEES).
// Contact properties: latest webinar facts plus running totals. Totals are
// guarded by the webinar UUID already stored on the contact, so a replay
// never counts the same webinar twice.
// Custom events (timeline): registered · joined · left · attended ·
// qa_participated, sent together through /events/v3/send/batch.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

let crypto = null; try { crypto = require('crypto'); } catch (e) { crypto = null; }
const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const CREATE_REG = flag('CREATE_CONTACT_ON_REGISTRATION', true);
const CREATE_ATT = flag('CREATE_CONTACT_FOR_ATTENDEES', false);
const JOIN_LEAVE_EVENTS = flag('SEND_JOIN_LEAVE_EVENTS', true);
const placeholder = (v) => !v || /^YOUR_/i.test(String(v));
const sandbox = !!($json && $json.simulatedContact);
const ctx = sandbox ? $json : $('Build Contact Lookup').item.json;
const res = sandbox ? $json.simulatedContact : $json;
const P = ctx.prefix; const g = ctx.engagement; const w = ctx.webinar;
let portal = env('HUBSPOT_PORTAL_ID', '');
if (placeholder(portal) && SANDBOX_MODE && ctx.sandboxFixtures) portal = ctx.sandboxFixtures.portalId;
